          "Vóór de zee en het land en de hemel die alles bedekt",
          "was er in de hele wereld één gezicht van de natuur,",
          "dat men chaos noemde: een ruwe, ongeordende massa,",
          "niets dan dood gewicht, en in hetzelfde punt samengehoopt",
          "de onharmonieuze kiemen van slecht verbonden dingen.",
          "Nog verlichtte geen Titan de wereld,",
