          "Deze strijd beëindigde een god en een betere orde der natuur.",
          "Want hij scheidde de aarde van de hemel en het water van het land",
          "en de heldere hemel van de dichte lucht.",
          "Toen hij de elementen had ontward en uit de duistere hoop bevrijd,",
