          "Hij beval de vlakten zich uit te strekken, de valleien te dalen,",
          "de bossen zich met loof te bedekken, de steenachtige bergen te rijzen,",
          "en zoals twee zones de hemel rechts en evenveel links",
          "doorsnijden, en een vijfde heter is dan die,",
          "zo onderscheidde de zorg van de god het omsloten gewicht in hetzelfde aantal,",
          "en evenveel streken drukken op de aarde.",
          "Waarvan de middelste onbewoonbaar is door de hitte;",
          "diepe sneeuw bedekt de twee polen; evenveel plaatste hij ertussen",
          "en gaf ze een gematigd klimaat van warmte gemengd met koude.",
          "Daarboven hangt de lucht, die zoveel zwaarder is dan vuur",
          "als het gewicht van water lichter is dan dat van de aarde.",
          "Daar beval hij de nevels en wolken zich te vestigen",
          "en donders die de menselijke geest doen beven",
          "en winden die met bliksemflitsen bliksemschichten maken.",
          "Ook de lucht stond de maker van de wereld niet onbeperkt toe",
          "aan deze toe; zelfs nu worden zij nauwelijks tegengehouden,",
          "hoewel elk zijn vlagen in een verschillende richting stuurt,",
          "van het verscheuren van de wereld; zo groot is de tweedracht der broers.",
          "Eurus week terug naar Aurora en de Nabatese rijken",
          "en Perzië en de bergtoppen onder het ochtendlicht;",
          "de avond en de kusten die gloeien in de ondergaande zon",
          "zijn het dichtst bij Zephyrus; het ijzige Scythië en de Grote Beer",
