          "wordt doorweekt door aanhoudende wolken en regen van de Zuidenwind.",
          "Hierboven plaatste hij de doorzichtige, gewichtloze",
          "ether, vrij van elk aards bezinksel.",
          "Nauwelijks had hij alles zo binnen vaste grenzen gescheiden,",
