          "ontbrak nog, een dat over de rest kon heersen:",
          "de mens werd geboren, hetzij de goddelijke schepper hem",
          "maakte uit goddelijk zaad, oorsprong van een betere wereld,",
          "hetzij de pas geschapen aarde, kort tevoren gescheiden van de hoge",
          "ether, nog verwante hemelse kiemen bevatte.",
          "Die mengde Prometheus, de zoon van Iapetus, met regenwater",
          "en vormde ze naar het beeld van de allesbesturende goden,",
          "en terwijl de andere dieren naar de grond kijken,",
          "gaf hij de mens een opgeheven gelaat en beval hem",
          "naar de hemel te kijken en zijn blik op te heffen naar de sterren:",
          "zo nam de aarde, die kort tevoren ruw en vormloos was geweest,",
          "de onbekende gestalten van mensen aan.",
          "Het gouden tijdperk was als eerste gezaaid, dat zonder bestraffer,",
          "uit eigen beweging, zonder wet, trouw en het goede vereerde.",
          "Straf en angst ontbraken; er werden geen dreigende woorden",
          "in brons gegraveerd gelezen; geen smekende menigte vreesde",
          "het gezicht van haar rechter: zonder bestraffer waren zij veilig.",
          "Nog was geen pijnboom, op haar eigen bergen gekapt,",
          "in de vloeibare golven afgedaald om vreemde landen te bezoeken;",
          "en geen stervelingen kenden andere kusten dan de hunne;",
          "nog omringden geen steile grachten de steden;",
          "geen rechte trompet, geen gebogen koperen hoorn,",
          "geen helm, geen zwaard bestond: zonder leger",
          "brachten de volkeren hun dagen door in zachte vrede en rust.",
          "De aarde zelf ook, ongeploegd en door geen houweel aangeraakt",
          "en door geen ploegijzer gewond, gaf uit zichzelf alles,",
          "en tevreden met voedsel dat zonder dwang was gegroeid",
          "plukten zij aardbeien en bergframbozen",
          "en kornoeljen en aan de ruwe braamstruiken hangende moerbeien",
          "en de eikels die van Jupiters brede boom waren gevallen.",
          "De lente was eeuwig, en zachte westwinden streelden",
          "met warme lucht de bloemen die zonder zaad waren gegroeid;",
          "weldra droeg de ongeploegde aarde ook vruchten,",
          "en het niet-vernieuwde veld werd wit van zware korenaren;",
          "er vloeiden rivieren van melk en rivieren van nectar,",
          "en gele honing druppelde van de groene steeneik.",
          "Nadat Saturnus naar het duistere Tartarus was gezonden",
          "en de wereld onder Jupiter stond, kwam het zilveren geslacht,",
          "slechter dan het gouden, kostbaarder dan het gele brons.",
          "Jupiter bekortte de duur van de lente van weleer",
          "en liet door winters en zomers en ongelijke herfsten",
          "en een korte lente het jaar verlopen in vier periodes.",
          "Toen eerst gloeide de lucht wit, verschroeid door droge hitte,",
          "en hing ijs, vastgemaakt door de wind;",
          "toen eerst betraden zij huizen; huizen waren grotten",
          "en dichte struiken en met bast samengebonden twijgen.",
          "Toen eerst werden de zaden van Ceres in lange voren",
          "begraven, en kreunden de jonge stieren onder het juk.",
          "Als derde volgde na die het bronzen geslacht op,",
          "woester van aard en sneller geneigd tot verschrikkelijke wapens,",
          "maar toch niet misdadig; van hard ijzer is het laatste.",
          "Onmiddellijk brak in het tijdperk van dat slechtere metaal",
          "alle kwaad los: schaamte, waarheid en trouw vluchtten;",
          "in hun plaats traden bedrog en list",
          "en hinderlagen en geweld en misdadige hebzucht.",
          "Zij spreidden de zeilen voor de wind, en de zeeman kende die",
          "nog niet goed; de kielen, die eerst op hoge bergen hadden gestaan,",
          "dansten op onbekende golven;",
          "en de grond, die eerst als het zonlicht en de lucht gemeenschappelijk was,",
          "merkte de voorzichtige landmeter af met lange grenzen.",
          "Niet alleen oogsten en verschuldigd voedsel",
          "eiste men van de rijke bodem, maar men drong door in de ingewanden der aarde,",
          "en de schatten die zij had verborgen en naar de Stygische schaduwen gebracht,",
