          "gruwelijke stiefmoeders mengen dodelijk gif;",
          "de zoon vraagt vóór de tijd naar de jaren van zijn vader:",
          "de vroomheid ligt verslagen, en de maagd Astraea, de laatste",
          "van de hemelbewoners, verliet de met bloed doordrenkte aarde."
